def translate_ui(text, language="en", **values):
    text = str(text)
    translated = EXTRA_TRANSLATIONS.get(language, {}).get(
        text, TRANSLATIONS.get(language, {}).get(text, text)
    )
    return translated.format(**values) if values else translated
